      float3 circle(float2 p, float amzLocal_size, float decay, float3 color,float3 color2, float dist, float2 mouse)
      {
          float l = length(p + mouse*(dist*4.))+amzLocal_size/2.;
          float l2 = length(p + mouse*(dist*4.))+amzLocal_size/3.;
          float c = max(00.01-pow(length(p + mouse*dist), amzLocal_size*1.4), 0.0)*50.;
          float c1 = max(0.001-pow(l-0.3, 1./40.)+sin(l*30.), 0.0)*3.;
          float c2 = max(0.04/pow(length(p-mouse*dist/2. + 0.09)*1., 1.), 0.0)/20.;
          float s = max(00.01-pow(regShape(p*5. + mouse*dist*5. + 0.9, 6) , 1.), 0.0)*5.;
          color = 0.5+0.5*sin(color);
          color = cos(float3(amzp_color1.rgb)*8. + dist*4.)*0.5+.5;
        float3 f = c*color ;
          f += c1*color;
          f += c2*color;
          f += s*color;
