    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = amzScreenNorm();
        satriyaid /= (amzp_position.z/100.0);
        satriyaid += float2((230.0+amzp_position.x), (-130.0+amzp_position.y))*float2(-1.,1.)/500.;
     float4 fragColor;
          float2 uv = satriyaid;
          uv.x*=screen.zw.x/screen.zw.y;
          float2 mm = uv;
           mm = float2(sin(amzp_progressc/6.)/1., cos(amzp_progressd/4.0)/2. )/2.;
          float3 circColor = float3(0.9, 0.2, 0.1);
          float3 circColor2 = float3(0.3, 0.1, 0.9);
          float3 color = mix(float3(amzp_color3.rgb)/0.9, float3(amzp_color4.rgb), uv.y)*amzp_progressb;
          for(float i=0.;i<10.;i++){
              color += circle(uv, pow(rnd(i*2000.)*amzp_progressa, 2.)+1.41, 0.0, circColor+i , circColor2+i, rnd(i*20.)*3.+0.2-.5, mm);
          }
            float a = atan(uv.y-mm.y, uv.x-mm.x);
           float l = max(1.0-length(uv-mm)-0.84, 0.0);
          float bright = amzp_progresse;
          color += max(0.1/pow(length(uv-mm)*5., 5.), 0.0)*abs(sin(a*5.+cos(a*9.)))/20.;
          color += max(0.1/pow(length(uv-mm)*10., 1./20.), .0)+abs(sin(a*3.+cos(a*9.)))/8.*(abs(sin(a*9.)))/1.;
          color += (max(bright/pow(length(uv-mm)*4., 1./2.), 0.0)*4.)*float3(0.2, 0.21, 0.3)*4.;
            color*= exp(1.0-length(uv-mm))/5.;
       fragColor = float4(color,1.0);
     float4 factor = mix(texColorX,fragColor,amzp_alpha);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * 1.0) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= 1.0;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= 1.0;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = resultfinal;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
